<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
import { schools as getSchools } from '../campus-community/api'
import * as api from './api'
const route = useRoute()
const keyword = ref(typeof route.query.q === 'string' ? route.query.q : ''), type = ref(''), school = ref(''), schools = ref<{ id: string; name: string }[]>([]), result = ref<api.Results | null>(null), busy = ref(false), message = ref(''), selected = ref<Awaited<ReturnType<typeof api.detail>> | null>(null)
async function search(page = 1) { if (!keyword.value.trim()) return; busy.value = true; message.value = ''; selected.value = null; try { result.value = await api.search(keyword.value.trim(), type.value, school.value, page) } catch (e) { result.value = null; message.value = e instanceof Error ? e.message : '搜索失败' } finally { busy.value = false } }
async function detail(hit: api.Hit) { busy.value = true; message.value = ''; try { selected.value = await api.detail(hit) } catch (e) { selected.value = null; message.value = e instanceof Error ? e.message : '内容可能已下架，请重新搜索' } finally { busy.value = false } }
onMounted(async () => { try { schools.value = await getSchools() } catch {} if (keyword.value.trim()) await search() })
watch(() => route.query.q, value => { if (typeof value === 'string' && value !== keyword.value) { keyword.value = value; void search() } })
</script>
<template><section><h1>搜索校园周边</h1><form class="inline-form" @submit.prevent="search()"><div><label for="globalKeyword">关键词</label><input id="globalKeyword" v-model.trim="keyword" maxlength="100" required /></div><div><label for="globalType">内容类型</label><select id="globalType" v-model="type"><option value="">全部内容</option><option v-for="(label, value) in api.typeLabels" :key="value" :value="value">{{ label }}</option></select></div><div><label for="globalSchool">校园</label><select id="globalSchool" v-model="school"><option value="">全部校园</option><option v-for="s in schools" :key="s.id" :value="s.id">{{ s.name }}</option></select></div><button :disabled="busy">搜索</button></form><p v-if="message" role="status">{{ message }}</p>
  <template v-if="result"><p class="muted">找到 {{ result.total }} 条{{ result.windowLimited ? '窗口内结果，请缩小关键词或筛选范围' : '结果' }}</p><article v-for="hit in result.items" :key="`${hit.resourceType}:${hit.id}`" class="workspace-card"><span class="badge">{{ api.typeLabels[hit.resourceType] }}</span><h2><template v-for="(part, i) in hit.titleSegments" :key="i"><mark v-if="part.matched">{{ part.text }}</mark><template v-else>{{ part.text }}</template></template></h2><p class="post-body"><template v-for="(part, i) in hit.excerptSegments" :key="i"><mark v-if="part.matched">{{ part.text }}</mark><template v-else>{{ part.text }}</template></template></p><RouterLink v-if="hit.resourceType === 'POST'" class="text-link" :to="`/community/posts/${hit.id}`">查看帖子 →</RouterLink><button v-else class="secondary" :disabled="busy" @click="detail(hit)">查看当前详情</button></article><PaginationBar :page="result.page" :size="20" :total="result.total" :disabled="busy" @change="search" /></template>
  <article v-if="selected" class="workspace-card"><h2>{{ selected.title ?? selected.name }}</h2><p>{{ selected.description }}</p><p v-if="selected.address">{{ selected.address }}</p><p v-if="selected.price">每份 ¥{{ selected.price }}</p><p v-if="selected.rules">满 {{ selected.rules.threshold }} 元 · {{ selected.couponType === 'AMOUNT_OFF' ? `减 ${selected.rules.amountOff} 元` : `按 ${Number(selected.rules.discountRate) * 10} 折结算` }}</p><div class="button-row"><RouterLink class="text-link" to="/app">前往优惠中心 →</RouterLink><RouterLink class="text-link" to="/trade">前往套餐页 →</RouterLink></div></article>
</section></template>
